    #[test]
    fn search_and_generation_use_typed_provider_operations() {
        let (_project_dir, _storage_dir, project, mut manifest, mut host, run) = setup("typed");
        grant_acquisition(&mut host, &run, true);
        let cancellation = AssetAcquisitionCancellation::default();
        let context = AssetProviderContext::new(Some("search-secret"), &cancellation);
        let mut provider = MockProvider::default();
        let results = AgentAssetAcquisitionService::search(
            &mut host,
            &run,
            &mut provider,
            &AssetSearchRequest {
                query: "tree".to_owned(),
                limit: 10,
            },
            &context,
        )
        .expect("search");
        assert_eq!(results.len(), 1);
        assert_eq!(
            results[0].source_reference.as_deref(),
            Some("https://catalog.test/assets/asset-42")
        );
        let generated = AgentAssetAcquisitionService::execute(
            &mut host,
            &run,
            &project,
            &mut manifest,
            &mut provider,
            &AssetAcquisitionRequest {
                request_id: "generate-one".to_owned(),
                operation: AssetProviderOperation::Generate {
                    kind: GeneratedAssetKind::Image,
                    prompt: "a tree icon".to_owned(),
                },
                destination_folder: PathBuf::from("textures"),
                explicit_user_decision: true,
            },
            &context,
        )
        .expect("generation");
        assert_eq!(generated.assets.len(), 1);
        assert_eq!(provider.calls, 2);
    }
